-- 2026-11-11 1.4.1 输入设备概述：1）–5）各自成行，2）–5）补齐绿/红标记
begin;
create temp table _kb14(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kb14 values (53, $kb14$[{"t":"list","id":"a1-1-4-1-b1","imp":"core","items":["1、==键盘、鼠标、笔输入设备、扫描仪、数字摄像头概述==","^^1）键盘^^：==用于操作计算机设备运行的指令和数据输入装置==，也指经过系统安排操作一台机器或设备的一组功能键（如打字机、电脑键盘）。","^^2）鼠标^^：==计算机的一种外接输入设备，也是计算机显示系统纵横坐标定位的指示器。==","^^3）笔输入设备^^：==主要有手写板、手写笔。==","^^4）扫描仪^^：==一种捕获影像的装置，作为光机电一体化的电脑外设产品，可将影像转换为计算机可以显示、编辑、存储和输出的数字格式。==","^^5）数字摄像头^^：==可以将视频采集设备产生的模拟视频信号转换成数字信号，进而将其储存在计算机里。==","2、==外部设备包括输入设备和输出设备==：外部设备包括==输入设备和输出设备==。扫描仪是输入设备，常见的输入设备还有鼠标、键盘、手写板等。","3、==扫描仪的主要性能指标==：^^1）光学分辨率（dpi）^^：==反映图像大小==，分辨率越高，扫描后的图像越大、越清晰，例如1200×2400 dpi；扫描仪的分辨率决定了扫描仪的档次和价格。 2）色彩位数（色彩深度）：反映色彩逼真度，色彩位数越多，图像越真实，例如32 bit。 3）扫描幅面：指被扫描原稿的最大尺寸，例如A3、A4等。 4）与主机的接口类型：SCSI、USB、IEEE 1394接口。","4、==汉字输入编码与内码==：==用不同的输入编码方法输入同一个汉字==，其内码是一样的。联机手写汉字识别使用笔输入设备；印刷体汉字识别输入使用扫描仪和OCR。","5、==键盘与鼠标==：==计算机必备的输入设备是键盘==，鼠标是最常用的输入设备。","6、==扫描仪的分类==：手持式扫描仪、平板式扫描仪（家用和办公自动化领域广泛应用）、胶片专用扫描仪和滚筒式扫描仪（专业印刷排版领域）。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-4-1-b2","imp":"core","kind":"tip","text":"常见输入设备：键盘、鼠标、触摸屏、手写板、图形数字化仪、扫描仪、摄像头；扫描仪核心指标是==光学分辨率（DPI，每英寸点数）与色彩深度（如 24 位/48 位真彩色）==；鼠标主要性能参数包括==分辨率（DPI）与刷新率==。","title":"考向复习提示：常用输入设备分类及技术指标"},{"t":"callout","id":"a1-1-4-1-b3","imp":"core","kind":"trap","text":"键盘上敲击一个按键向主机发送的是硬件==扫描码（与按键物理位置相关）==，而不是字符的 ASCII 码；操作系统键盘驱动程序负责将扫描码根据当前的 Shift/CapsLock 状态转换为对应的 ASCII 码或汉字机内码；专转本常考单选：按下键和松开键会分别产生通码和断码。","title":"高频易错陷阱：扫描码与 ASCII 码的区别"}]$kb14$::jsonb, $kb14se$A1-1.4.1 键盘，鼠标，笔输入设备，扫描仪，数字摄像头概述。 1、键盘、鼠标、笔输入设备、扫描仪、数字摄像头概述 1）键盘：用于操作计算机设备运行的指令和数据输入装置，也指经过系统安排操作一台机器或设备的一组功能键（如打字机、电脑键盘）。 2）鼠标：计算机的一种外接输入设备，也是计算机显示系统纵横坐标定位的指示器。 3）笔输入设备：主要有手写板、手写笔。 4）扫描仪：一种捕获影像的装置，作为光机电一体化的电脑外设产品，可将影像转换为计算机可以显示、编辑、存储和输出的数字格式。 5）数字摄像头：可以将视频采集设备产生的模拟视频信号转换成数字信号，进而将其储存在计算机里。 2、外部设备包括输入设备和输出设备：外部设备包括输入设备和输出设备。扫描仪是输入设备，常见的输入设备还有鼠标、键盘、手写板等。 3、扫描仪的主要性能指标：1）光学分辨率（dpi）：反映图像大小，分辨率越高，扫描后的图像越大、越清晰，例如1200×2400 dpi；扫描仪的分辨率决定了扫描仪的档次和价格。 2）色彩位数（色彩深度）：反映色彩逼真度，色彩位数越多，图像越真实，例如32 bit。 3）扫描幅面：指被扫描原稿的最大尺寸，例如A3、A4等。 4）与主机的接口类型：SCSI、USB、IEEE 1394接口。 4、汉字输入编码与内码：用不同的输入编码方法输入同一个汉字，其内码是一样的。联机手写汉字识别使用笔输入设备；印刷体汉字识别输入使用扫描仪和OCR。 5、键盘与鼠标：计算机必备的输入设备是键盘，鼠标是最常用的输入设备。 6、扫描仪的分类：手持式扫描仪、平板式扫描仪（家用和办公自动化领域广泛应用）、胶片专用扫描仪和滚筒式扫描仪（专业印刷排版领域）。 考向复习提示：常用输入设备分类及技术指标 常见输入设备：键盘、鼠标、触摸屏、手写板、图形数字化仪、扫描仪、摄像头；扫描仪核心指标是光学分辨率（DPI，每英寸点数）与色彩深度（如 24 位/48 位真彩色）；鼠标主要性能参数包括分辨率（DPI）与刷新率。 高频易错陷阱：扫描码与 ASCII 码的区别 键盘上敲击一个按键向主机发送的是硬件扫描码（与按键物理位置相关），而不是字符的 ASCII 码；操作系统键盘驱动程序负责将扫描码根据当前的 Shift/CapsLock 状态转换为对应的 ASCII 码或汉字机内码；专转本常考单选：按下键和松开键会分别产生通码和断码。$kb14se$);
do $$
declare r record; old_rev record; v_rev integer;
begin
  for r in select node_id, blocks, search_text from _kb14 loop
    select rev_no, html, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 找不到已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v_rev, r.blocks, old_rev.html, r.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
